  "4 to 8 digits: the code is asked before opening, against accidental taps. Empty = confirm only.":
    "4〜8桁：誤タップ防止のため、開く前にコードを求めます。空欄=確認のみ。",
  "4 · What gets sent": "4 · 送られるもの",
  "Twenty seconds with no image: it may be off, or just very slow":
    "20秒間まったく映像がありません。電源が切れているか、単に非常に遅いだけかもしれません",
