  "A valid calendar.* entity is required.": "有効な calendar.* エンティティが必要です。",
  "A valid entity is required (domain.name).": "有効なエンティティが必要です（domain.name）。",
  "A valid person.* or device_tracker.* entity is required.":
    "有効なperson.*またはdevice_tracker.*エンティティが必要です。",
  "A valid todo.* entity is required.": "有効な todo.* エンティティが必要です。",
  "A valid vacuum.* or lawn_mower.* entity is required.":
    "有効な vacuum.* または lawn_mower.* エンティティが必要です。",
