  "Enough on its own: on and off, no numbers.": "これだけで足ります: 入と切、数字なしで。",
  "Enough on its own: the card says on and off, and does not pretend to know the degrees.":
    "これだけで十分です。カードは運転と停止を示し、知らない温度を装いません。",
