  Error: "エラー",
  "Estimated time": "推定時間",
  Events: "イベント",
  "Every area is a Home Assistant panel of its own, with its own arming modes. The one marked “on the page now” is what the dial and the keypad are commanding: the eye beside another one brings it on screen in its place.":
    "エリアごとに独立した Home Assistant のパネルがあり、それぞれの警戒モードを持ちます。「いまページに表示中」と付いているものを、ダイヤルとキーパッドが操作しています: 別のエリアの横の目を押すと、そちらが代わりに画面に出ます。",
  "Every field is optional: the card automatically shows what is available. Start, duration, energy and cost of the last cycle are computed automatically from power transitions unless you provide dedicated entities.":
    "項目はすべて任意です。カードは揃っているものだけを自動で表示します。前回の運転の開始・所要時間・電力量・費用は、専用のエンティティを指定しないかぎり電力の変化から自動で計算されます。",
  "Every filled box must be a cover.* or switch.* entity.":
    "入力した欄はすべて cover.* または switch.* エンティティである必要があります。",
  "Every load below is a circle of the Energy flow, under Home, in the order of this list. What you write here is what the flow shows, and the devices you file under it are the ones that appear when you tap the circle.":
    "下の負荷はそれぞれ、ホームの下にあるエネルギーフローの円で、並び順はこのリストのとおりです。ここに書いた内容がフローに表示され、その下に入れた機器が円をタップしたときに並びます。",
  "Every plant has its own meter, its own solar, its own battery and its own loads. The fields below belong to the selected plant: adding one starts from scratch and leaves what you already configured alone.":
    "設備ごとにメーター、太陽光、蓄電池、負荷があります。下の欄は選択中の設備のものです。追加するとゼロから始まり、すでに設定したものには触れません。",
  "Every plant has its own thirteen fields. The one marked “on the page now” is what the Solar thermal page and the Home tile are showing: the eye beside another one brings it on screen in its place.":
    "設備ごとに十三の項目があります。「いまページに表示中」と付いているものが、太陽熱のページとホームのタイルに出ているものです: 別の設備の横の目を押すと、そちらが代わりに画面に出ます。",
  "Everything is here: the window's card shows its room's humidity and says to open as soon as it goes above the threshold.":
    "準備完了：窓のカードはその部屋の湿度を表示し、しきい値を超えるとすぐに開けるよう勧めます。",
  "Everything off": "すべてオフ",
  "Everything on the repository": "リポジトリにあるものすべて",
  "Everything the dashboard can do, and whether it shows. The same switch is also at the top of each section's own tab: here they are all together, so you can see what exists without opening them one by one.":
    "ダッシュボードでできることと、それが表示されるかどうか。同じスイッチは各セクションのタブの先頭にもあります。ここでは全部まとめてあるので、一つずつ開かなくても何があるか分かります。",
