  "Fireplace pump": "暖炉のポンプ",
  "First configure the circles connected to Home. Each circle can use a direct power sensor or automatically sum every child of a load group. Then create the appliances inside each group. Empty or disabled nodes are not forced into the flow.":
    "まずホームにつながる円を設定します。各円は直接の電力センサーを使うか、そのグループに属する負荷を自動で合計できます。次に各グループの中に家電を作成します。空のノードや無効なノードがフローに押し込まれることはありません。",
  "First select your lights in the Lights step (or wizard).":
    "まず「照明」の手順（またはウィザード）で照明を選んでください。",
  Fixed: "固定",
  "Fixed cycle duration (minutes)": "運転時間を固定（分）",
  "Flap opened": "投入口が開いた",
  "Flightradar24 exposes “current in area”: the count, with the list of flights in the attributes.":
    "Flightradar24 は「current in area」を公開します。件数と、属性に航空機の一覧が入ります。",
  "Flights in the area": "周辺の航空機",
  "Flights overhead": "上空の航空機",
  "Flip the direction (ON = closed)": "向きを反転（ON = 閉）",
  "Flip the percentages (100 = closed)": "パーセントを反転（100 = 閉）",
