  Home: "ホーム",
  "Home (fallback)": "ホーム（代替）",
  "Home Assistant declares no machine and no network piece.":
    "Home Assistant はマシンもネットワーク機器も報告していません。",
  "Home Assistant declares the air sensors itself — particulates, CO₂, monoxide, volatile compounds — and the tile appears on its own. Here you correct that: drop a sensor that should not count, add one that is not found, and move the boundaries between good, fair, poor and bad.":
    "空気センサーは Home Assistant が自分で申告します（粒子状物質、CO₂、一酸化炭素、揮発性化合物）。タイルは自動で現れます。ここではそれを直します。数えたくないセンサーを外し、見つからないものを足し、良好・普通・悪い・非常に悪いの境界を動かします。",
  "Home Assistant did not take the scheduled switch-off: update the integration and try again.":
    "Home Assistant が予約消灯を受け付けませんでした。統合を更新してからもう一度お試しください。",
  "Home Assistant does not allow you to command this entity: it needs a user with permission, or the entity is exposed read-only.":
    "Home Assistant はこのエンティティの操作を許可していません。権限のあるユーザーが必要か、エンティティが読み取り専用で公開されています。",
  "Home Assistant entity": "Home Assistant のエンティティ",
  "Home Assistant entity for the new light": "新しい照明の Home Assistant エンティティ",
  "Home Assistant entity, e.g.": "Home Assistant のエンティティ、例:",
  "Home Assistant history is unavailable for the selected period.":
    "選択した期間の Home Assistant 履歴は利用できません。",
  "Home Assistant integrations, official or from HACS, with the devices they bring. Pick the bowl, the litter box or the collar: the card's fields fill themselves in.":
    "Home Assistant の統合（公式でも HACS でも）と、そこに含まれる機器の一覧です。食器やトイレ、首輪を選ぶと、カードの欄が自動で埋まります。",
  "Home Assistant integrations, official or from HACS, with the devices they bring. Pick the device: the fields come along by themselves.":
    "Home Assistant の統合（公式または HACS）と、そこに含まれるデバイス。デバイスを選ぶと、各項目はひとりでに埋まります。",
  "Home Assistant integrations, official or from HACS, with the devices they bring. Pick the node: status, CPU, memory, disk and degrees come along by themselves.":
    "Home Assistant の統合（公式または HACS）と、そこに含まれる機器の一覧です。ノードを選べば、状態、CPU、メモリ、ディスク、温度が自動で入ります。",
  "Home Assistant integrations, official or from HACS, with the devices they bring. Pick your TV or speaker: its entity, the controls the integration publishes next to it and its readings come along by themselves.":
    "Home Assistant の統合（公式または HACS）と、そこに含まれる機器の一覧です。テレビやスピーカーを選べば、そのエンティティ、統合が隣に公開している操作、測定値が自動で入ります。",
  "Home Assistant integrations, official or from HACS, with the devices they bring. Pick your appliance: every entity comes along, and the card fields fill themselves in.":
    "Home Assistant の統合（公式または HACS 製）と、それが持つデバイス。家電を選ぶと、すべてのエンティティが一緒に入り、カードの項目は自動で埋まります。",
  "Home Assistant integrations, official or from HACS, with the devices they bring. Pick your car: battery or tank, range, odometer, doors and the rest come along by themselves.":
    "Home Assistant の統合（公式または HACS）と、それが持つデバイス。あなたの車を選べば、バッテリーまたは燃料タンク、航続距離、走行距離計、ドアなどが自動で入ります。",
  "Home Assistant integrations, official or from HACS, with the devices they bring. Pick your robot: its entity, its maps, the battery, its programs and its readings come along by themselves.":
    "Home Assistant の統合（公式または HACS）と、そこに含まれる機器の一覧です。ロボットを選べば、そのエンティティ、マップ、バッテリー、プログラム、測定値が自動で入ります。",
  "Home Assistant is not answering": "Home Assistant が応答しません",
  "Home Assistant is not connected": "Home Assistant に接続していません",
  "Home Assistant keeps the countdown: you can close the dashboard and the unit still switches off.":
    "カウントダウンは Home Assistant が持ちます。ダッシュボードを閉じても、ちゃんと消えます。",
  "Home Assistant language": "Home Assistant の言語",
  "Home Assistant media folders": "Home Assistant のメディアフォルダー",
  "Home Assistant refused the target": "Home Assistant がターゲットを拒否しました",
  "Home Assistant to-do lists: tick them off from the Home tile and from the Agenda section, and the ones with a due date show up on the day they are due.":
    "Home Assistant のやることリスト。ホームのタイルと予定表のセクションからチェックでき、期限のあるものは期限の日に現れます。",
  "Home Assistant version": "Home Assistant のバージョン",
  "Home Assistant water heater": "Home Assistant の給湯器",
  "Home Assistant · Core system": "Home Assistant · コアシステム",
  "Home Assistant's Recorder took too long to answer. That happens when the history is large or the server is small: it retries on its own, and if it keeps happening it is worth lowering the days the Recorder keeps (purge_keep_days) or excluding entities you do not need.":
    "Home Assistant の Recorder の応答に時間がかかりすぎました。履歴が大きいかサーバーが小さいときに起こります：自動で再試行しますが、頻発する場合は Recorder が保持する日数を減らす（purge_keep_days）か、不要なエンティティを除外するとよいです。",
  "Home consumption": "住宅の消費",
  "Home consumption power (W)": "家全体の消費電力 (W)",
  "Home consumption · Month": "家の消費 · 今月",
  "Home consumption · Today": "家の消費 · 今日",
