  "I could not read the queue:": "一覧を読めませんでした:",
  "I do not know": "わかりません",
  "I do not know where home is: Home Assistant did not answer. Pick a zone or write the coordinates.":
    "自宅の場所がわかりません。Home Assistant が応答しませんでした。ゾーンを選ぶか座標を入力してください。",
  "I would like it to": "こうしてほしい",
  "I'll take it": "担当する",
  "IKEA's Vallhorn, a Zigbee contact on the flap, a light sensor… pick the mailbox device and whichever fields that integration publishes fill themselves in. One sensor alone is enough too.":
    "IKEA の Vallhorn、Zigbee の接点、照度センサー… 郵便受けの中のデバイスを選べば、二つの項目はひとりでに埋まります。 センサーは1つでも十分です。",
  INSTANT: "瞬時",
  Icon: "アイコン",
