  "The data comes from the supplier's integration. Pick the sensors in Config → Energy → Settings.":
    "データは電力会社の連携から届きます。センサーは 設定 → エネルギー → 設定 で選びます。",
  "The supplier integration's sensors. Empty means the dashboard finds them.":
    "電力会社の連携のセンサー。空欄の場合はダッシュボードが自動で探します。",
  "To pay": "未払い",
  "Total billed": "請求合計",
  years: "年",
  Unpaid: "未払い",
  "Add a supplier": "電力会社を追加",
  "After signing in the page stays blank or shows an error: that is normal.":
    "ログイン後、ページは白いままかエラーになります。これは正常です。",
  "An administrator is needed.": "管理者が必要です。",
  "Better from a computer: on a phone the supplier's app may open.":
    "パソコンからの方が確実です。スマートフォンでは電力会社のアプリが開くことがあります。",
  "Bills, consumption and contract come from the supplier and go to the Bills tab.":
    "請求書、使用量、契約は電力会社から届き、「請求書」タブに表示されます。",
  Connect: "接続",
  "Copy the address from the browser bar and paste it here.":
    "ブラウザのアドレスバーのアドレスをコピーしてここに貼り付けてください。",
  "Disconnect the supplier? Its sensors disappear and the access tokens are deleted.":
    "電力会社の接続を解除しますか？センサーが消え、アクセストークンは削除されます。",
  "Email or password is wrong.": "メールアドレスまたはパスワードが正しくありません。",
  "Energy suppliers": "電力会社",
  "minutes ago": "分前",
  "needs reconnecting": "再接続が必要",
  "No integration exists yet": "まだ連携がありません",
  "Open sign-in": "ログインを開く",
  "Open the supplier's sign-in and log in with your credentials.":
    "電力会社のログインページを開き、自分の情報でログインしてください。",
  "Page address": "ページのアドレス",
  "Pick your supplier": "電力会社を選択",
  Reconnect: "再接続",
  "SMS code": "SMS コード",
  Soon: "近日対応",
  "Supplier connected": "電力会社を接続しました",
  "The code is wrong, or expired.": "コードが正しくないか、期限切れです。",
  "The pasted address is not the right one: copy the one of the page after signing in.":
    "貼り付けたアドレスが正しくありません。ログイン後のページのアドレスをコピーしてください。",
  "The supplier does not answer. Try again shortly.":
    "電力会社から応答がありません。少し後でもう一度お試しください。",
  "The supplier sent a code by text message to your phone. Type it here.":
    "電力会社から SMS でコードが届きました。ここに入力してください。",
  "The supplier wants to check you are not a robot: you need to sign in from the browser.":
    "電力会社がロボットでないことを確認しようとしています。ブラウザからログインしてください。",
  updated: "更新",
  "Electricity · bills and consumption": "電気 · 請求書と使用量",
  "Electricity and gas · bills and consumption": "電気とガス · 請求書と使用量",
  "Too much time has passed: start over.": "時間が経ちすぎました。最初からやり直してください。",
  "After signing in the browser tries to open the E.ON app and fails: open the developer tools (F12), Console tab, and copy the line that contains “code=”.":
    "ログイン後、ブラウザが E.ON アプリを開こうとして失敗します。開発者ツール(F12)の「コンソール」タブを開き、「code=」を含む行をコピーしてください。",
  "Your customer-area credentials. They go through GdAHome, at home, only to sign in: the password is not saved, only the supplier's access tokens are kept.":
    "カスタマーエリアのログイン情報です。ログインのためだけに自宅の GdAHome を通ります。パスワードは保存されず、電力会社のアクセストークンのみ保持されます。",
  "Still reading the Recorder statistics": "Recorder の統計をまだ読み込んでいます",
