  "Switch (turns it on and off)": "スイッチ (入と切)",
  "Switch for": "スイッチ:",
  "Switch, light or scene to control — popups do not need one":
    "操作するスイッチ・照明・シーン — ポップアップには不要です",
  "Switch, light, fan or input_boolean used by the On/Off button.":
    "オン/オフのボタンが使う switch・light・fan・input_boolean です。",
