  "Synchronizing data…": "データを同期中…",
  "Syncing data...": "データを同期中...",
  Synthetics: "合成繊維",
  "System OK": "システム正常",
  "THIS field is what turns WebRTC on: the stream name as written inside go2rtc/Frigate. The camera name is not the lever.":
    "WebRTCを有効にするのはこの欄です:go2rtc/Frigateに書かれているストリーム名。カメラ名はレバーではありません。",
  "TIME REMAINING": "残り時間",
  TODAY: "今日",
  "TRV valve (position %)": "TRV バルブ（開度 %）",
  TV: "テレビ",
  "Take its own": "このカメラのものを使う",
  Taken: "担当中",
  "Taken by": "担当",
  "Taken from the grid · Today": "系統からの受電 · 今日",
