  Tan: "小麦色",
  Tank: "タンク",
  "Tap a room: each unit starts with its own steps":
    "部屋をタップ:各ユニットは自分の手順で起動します",
  "Tap a sensor": "センサーをタップ",
  "Tap an appliance to open its card.": "家電をタップするとカードが開きます。",
  "Tap the fan": "ファンをタップ",
  "Tap to change the mode": "タップしてモードを変更",
  "Tap to drop it from the chart": "タップしてグラフから外します",
  "Tap to open": "タップで開く",
  "Tap to open Energy": "タップしてエネルギーを開く",
  "Tap to put it back on the chart": "タップしてグラフに戻します",
  "Tap to rename": "タップで名前を変更",
  "Tap to rename the label": "タップでラベル名を変更",
  "Tap to turn on · cooling 26°C · auto fan": "タップでオン · 冷房 26°C · 風量自動",
  "Tapping a room": "部屋に触れると",
  Target: "設定値",
