  "Needs balancing above (mV)": "バランス調整が必要になる差 (mV)",
  "New pack": "新しいパック",
  "No battery pack": "バッテリーパックがありません",
  "No battery pack configured": "バッテリーパックが設定されていません",
  "No cells found": "セルが見つかりません",
  "No pack answering": "応答しているパックがありません",
  "No reading": "読み取り値なし",
  "One cell voltage per line, in cell order. You can paste them all at once, commas work too; “Find the cells” takes them from Home Assistant using the prefix of the pack's other entities.":
    "1行に1つのセル電圧を、セルの順に。まとめて貼り付けることもでき、カンマ区切りでも構いません。「セルを検索」はパックの他のエンティティの接頭辞を使ってHome Assistantから取得します。",
  "Optional: if the BMS does not publish it, the imbalance is worked out from the cells.":
    "任意: BMSが公開していない場合、不均衡はセルから計算されます。",
  "Other BMS": "その他のBMS",
