  "of ${minuti} min": "全${minuti}分",
  "open the drawer": "バスケットを開けてください",
  "Open/closed binary_sensor. Empty: uses the “Door entity”.":
    "開/閉の binary_sensor。空欄：「ドアのエンティティ」を使います。",
  "Program or recipe": "プログラムまたはレシピ",
  "Ready at ${ora}": "${ora}にできあがり",
  "Ready in ${durata}": "あと${durata}でできあがり",
  "Ready to start": "開始待ち",
  Remaining: "残り時間",
  Resume: "再開",
  "Seconds, minutes or hh:mm. Empty: uses the “Program duration”.":
    "秒、分、または hh:mm。空欄：「プログラムの所要時間」を使います。",
  "Seconds, minutes, hh:mm or the end time. Empty: uses the “Remaining time”.":
    "秒、分、hh:mm、または終了時刻。空欄：「残り時間」を使います。",
  "started at ${partita}": "${partita}に開始",
  "The controls show up when cooking starts": "調理が始まると操作ボタンが表示されます",
  "The entity_id given to services that do not name one. Empty: the cooking status.":
    "entity_id を指定しないサービスに渡す entity_id。空欄：調理の状態。",
  "The rest of the kitchen": "キッチンのほかの家電",
  "The temperature sensor.": "温度センサー。",
  "The timer is stopped until it resumes": "再開するまでタイマーは止まっています",
  "Time and temperature set: it only needs starting": "時間と温度は設定済み：あとは開始するだけ",
  "Total time": "合計時間",
  "under a minute": "1分未満",
  "What the “Cooking” entry of Appliances reads and presses. A control is an entity (button, switch, number, script) or a service with its parameters: philips_airfryer.adjust_time time=60 method=add. A button only shows up when its field is filled in, and only if it answers.":
    "家電の「調理」が読み取り、押すもの。操作はエンティティ（button、switch、number、script）か、パラメーター付きのサービスです：philips_airfryer.adjust_time time=60 method=add。ボタンは欄が入力されていて、応答する場合にだけ表示されます。",
  "Storage battery": "蓄電池",
  "💾 Stove saved": "💾 ストーブを保存しました",
  "A fan, a number or a select. Without it, the thermostat's fan modes are used, if it has any.":
    "fan、number、select のいずれか。なければ、サーモスタットに風量モードがあればそれを使います。",
  "A gas, pellet or wood boiler: flow, return, pressure, combustion.":
    "ガス・ペレット・薪のボイラー：往き、還り、圧力、燃焼。",
  "A number or a select, 1 to 5 or P1 to P5: on the page it becomes the dots with minus and plus.":
    "number か select（1〜5 や P1〜P5）。ページではマイナスとプラス付きのドットになります。",
  "A pellet stove in a room: the flame, the power, the fan and the hopper. More than one, too.":
    "部屋に置くペレットストーブ：炎、火力、ファン、タンク。複数台にも対応。",
  "A sensor with the alarm text or a binary_sensor: when it trips, the page shows the red banner with its words.":
    "アラーム文を出すセンサーか binary_sensor。作動するとページにその文言入りの赤い帯が出ます。",
  "Add stove": "ストーブを追加",
  "An electric water heater, fed by the PV plant or not.":
    "電気給湯器。太陽光発電で動かしていてもいなくても。",
  "As a percentage or in kg, like the boiler's; or a binary_sensor that turns on when the pellet is running low.":
    "ボイラーと同じくパーセントか kg。または、ペレットが少なくなるとオンになる binary_sensor。",
  "Brazier cleaning": "燃焼皿の掃除",
  "Check the stove's display.": "ストーブの表示を確認してください。",
  "Flame · Power · Pellet": "炎 · 火力 · ペレット",
  "For whoever has two hoppers: the page shows them side by side, Pellet 1 and Pellet 2, with the same threshold as the first.":
    "タンクが 2 つある場合：ページに並べて表示します（ペレット 1、ペレット 2）。しきい値は 1 つ目と同じです。",
  Ignition: "点火",
  "In alarm": "アラーム",
  "Living room stove": "リビングのストーブ",
  "Lower the power": "火力を下げる",
  Modulating: "出力調整中",
  "No stove configured": "ストーブは未設定です",
  "On its own it covers nearly everything: on and off, the target, the room temperature and, if it has them, the fan modes.":
    "これだけでほぼすべて揃います：入/切、設定値、室温、あればファンモードも。",
  "Pellet level, second hopper": "ペレット残量（2 つ目のタンク）",
  "Pellet OK": "ペレット十分",
  "Pellet running low": "ペレット残りわずか",
  "Power level": "火力",
  "Raise the power": "火力を上げる",
  "Roof collectors and a tank: the fields are the ones below.":
    "屋根の集熱器と貯湯タンク。項目は下にあります。",
  "Room temperature": "室温",
  "Save stove": "ストーブを保存",
  "Shutting down": "消火中",
  "Slow the fan down": "ファンを弱める",
  "Speed the fan up": "ファンを強める",
  Stove: "ストーブ",
  "Stove alarm": "ストーブのアラーム",
  "Stove controls": "ストーブの操作",
  "Stove phase": "ストーブの運転段階",
  "Stove thermostat": "ストーブのサーモスタット",
  "Switch (when there is no thermostat)": "スイッチ（サーモスタットがない場合）",
  "The stove heats the room it stands in: the page draws the flame, the power, the fan, the flue and the hopper, and gives you the buttons for on and off, the target, the power and the fan. No field is required: with just the thermostat the page already has almost everything. With more than one, add them here and the page grows a row to switch between them.":
    "ストーブは置かれている部屋を暖めます。ページには炎、火力、ファン、煙突、タンクが描かれ、入/切、設定値、火力、ファンのボタンが付きます。必須の項目はありません。サーモスタットだけでもほぼすべて揃います。複数ある場合はここで追加すると、ページに切り替え用の列が出ます。",
  "The word the stove shows on its display: ignition, working, brazier cleaning, shutdown… If the page does not know it, it shows it as it is.":
    "ストーブが表示に出す言葉：点火、運転、燃焼皿の掃除、消火… ページが知らない言葉はそのまま表示します。",
  "Without it, the thermostat's own reading is used.":
    "なければサーモスタット自身の測定値を使います。",
  Working: "運転中",
  "Air conditioners out of season": "シーズン外のエアコン",
  "Radiators out of season": "シーズン外のラジエーター",
