  "Valve with a position (cover): open above zero": "開度のあるバルブ（cover）：0 より上で開",
  Command: "コマンド",
  "▲ command": "▲ コマンド",
  "▼ command": "▼ コマンド",
  "Start command": "開始コマンド",
  "Mute command": "ミュートコマンド",
  "Stop command": "停止コマンド",
  "The dashboard doesn't know the arrows of ${nome}: the remote shows among the commands as an on/off button. Its commands go in «Other commands», as remote.name:command.":
    "ダッシュボードは${nome}の矢印キーを知りません：リモコンはコマンドの中にオン/オフボタンとして表示されます。コマンドは「その他のコマンド」に remote.name:command の形で追加します。",
  "Home Assistant doesn't say which integration this remote belongs to: it shows among the commands as an on/off button. Its commands go in «Other commands», as remote.name:command.":
    "Home Assistant はこのリモコンがどの統合のものか示していません：コマンドの中にオン/オフボタンとして表示されます。コマンドは「その他のコマンド」に remote.name:command の形で追加します。",
  "Device (optional)": "デバイス（任意）",
  "Remote device": "リモコンのデバイス",
  "Optional: the «device» of remote.send_command": "任意：remote.send_command の「device」",
  "The live picture on the left, arrows and zoom on the right, presets below. Each button presses an entity already in Home Assistant: a camera button, a script with onvif.ptz, or a remote with the command to send. A button without an entity stays off.":
    "左にライブ映像、右に矢印とズーム、下にプリセット。各ボタンは Home Assistant にすでにあるエンティティを押します：カメラのボタン、onvif.ptz を使うスクリプト、または送るコマンド付きのリモコン（remote）。エンティティのないボタンはオフのままです。",
  "Read level (optional)": "読み取りレベル（任意）",
  "Each channel is an upright fader with its mute: a player's volume, or a number (number, input_number) like a mixer's dB. A sensor becomes a meter you look at; a remote gets ▲ / ▼ and mute, each with its own command (remote.send_command). Mute is the player's own, a switch (on means muted), a remote or a button to press.":
    "各チャンネルはミュート付きの縦フェーダーです：プレーヤーの音量、またはミキサーの dB のような数値（number、input_number）。センサーは見るためのメーターになり、リモコン（remote）には ▲ / ▼ とミュートがあり、それぞれ独自のコマンドを送ります（remote.send_command）。ミュートはプレーヤー自身のもの、スイッチ（オンでミュート）、リモコン、または押すボタンです。",
  "What the integration publishes next to the player — a TV's power switch, the input dropdown, a scene: button.*, select.*, switch.* entities (plus input_*, script.*, scene.*). A remote.* turns on and off; written remote.name:command (for example remote.amp:volume_up) it sends that command. They appear on the card under the playback controls.":
    "統合がプレーヤーの横に公開するもの — テレビの電源スイッチ、入力の選択、シーン：button.*、select.*、switch.* のエンティティ（および input_*、script.*、scene.*）。リモコン remote.* はオン・オフし、remote.name:command と書くと（例：remote.amp:volume_up）そのコマンドを送ります。カードの再生ボタンの下に表示されます。",
  "Scale: to": "スケール：まで",
  "Scale: from": "スケール：から",
  "A button.*, select.*, switch.* or remote.* entity is required (also remote.name:command) — or input_button, input_select, input_boolean, script, scene.":
    "button.*、select.*、switch.* または remote.* のエンティティが必要です（remote.name:command も可）— または input_button、input_select、input_boolean、script、scene。",
  "A sensor with the level": "レベルを示すセンサー",
  "Empty: turns on": "空欄：オンにする",
  "Empty: turns off": "空欄：オフにする",
  "${inserite} of ${tutte} armed": "${inserite}/${tutte} 警戒中",
  "Add a command": "コマンドを追加",
  "Add a partition": "エリアを追加",
  "Add a reading": "読み取り値を追加",
  "Alarm · ${quante} areas": "警報 · ${quante}エリア",
  "Alarm partitions": "警報のエリア",
  "Buttons next to the readings: locks (lock and unlock), scripts, buttons, scenes, switches, blinds. A remote turns on and off; written remote.name:command it sends that command.":
    "読み取り値の横のボタン：錠（施錠と解錠）、スクリプト、ボタン、シーン、スイッチ、ブラインド。リモコン（remote）はオン・オフし、remote.name:command と書くとそのコマンドを送ります。",
  "Empty: all the ones from the dashboard's Security section":
    "空欄：ダッシュボードのセキュリティセクションのすべて",
  "Intercom / camera": "インターホン / カメラ",
  "Leaving and who is home": "外出と在宅者",
