  "Have the Echos say the notifications": "通知を Echo に読み上げさせる",
  "How it says it": "話し方",
  "Install the «Alexa Media Player» integration from HACS and sign in with your Amazon account: the Echos show up here by themselves.": "HACS から「Alexa Media Player」統合をインストールし、Amazon アカウントでサインインしてください。Echo はここに自動で表示されます。",
  "No Echo in Home Assistant": "Home Assistant に Echo がありません",
  "Notifications reach the phones; this way the Echos at home say them too, for whoever is home with their hands full. It applies to the whole home.": "通知はスマートフォンに届きます。これで家の Echo も読み上げます。家で手がふさがっている人のために。家全体に適用されます。",
