  "Tap an Echo to choose it. Several Echos play the same music, each on its own: to have it in sync use a speaker group from the Alexa app.": "Echo をタップして選びます。複数の Echo はそれぞれ同じ音楽を別々に再生します。同期させるには Alexa アプリのスピーカーグループを使ってください。",
